import LoginFooter from "./LoginFooter";
import Footer from "./Footer";
import LearnMore from "./LearnMore";
import Store from "./Store/Store";

/* =========================================================
   SESSION CHECK
========================================================= */

function hasValidLocalSession() {
  return (
    localStorage.getItem("isLoggedIn") === "true" &&
    Boolean(localStorage.getItem("sessionToken"))
  );
}

/* =========================================================
   PROTECTED DASHBOARD ROUTE
========================================================= */

function ProtectedRoute({ children }) {
  const [isAuthenticated, setIsAuthenticated] = useState(
    () => hasValidLocalSession()
  );

  useEffect(() => {
    const dashboardUrl = window.location.href;

    const checkSession = () => {
      const validSession = hasValidLocalSession();
      setIsAuthenticated(validSession);
    };

    /*
      Add a protected history entry.

      This makes the mobile browser Back button
      stay on the dashboard while the session is valid.
    */

    if (
      !window.history.state?.protectedDashboard
    ) {
      window.history.pushState(
        {
          ...(window.history.state || {}),
          protectedDashboard: true,
        },
        "",
        dashboardUrl
      );
    }

    /*
      Handle browser Back navigation.

      Capture phase is used so this handler runs
      before React Router processes the popstate event.
    */

    const handlePopState = () => {
      if (hasValidLocalSession()) {
        window.history.pushState(
          {
            ...(window.history.state || {}),
            protectedDashboard: true,
          },
          "",
          dashboardUrl
        );
      } else {
        setIsAuthenticated(false);
      }
    };

    window.addEventListener(
      "popstate",
      handlePopState,
      true
    );

    // Check when restored from browser history / cache
    window.addEventListener("pageshow", checkSession);

    // Check when storage changes in another tab
    window.addEventListener("storage", checkSession);

    // Check when logout is triggered
    window.addEventListener(
      "golden-dreams-logout",
      checkSession
    );

    // Check when returning to the browser tab
    document.addEventListener(
      "visibilitychange",
      checkSession
    );

    checkSession();

    return () => {
      window.removeEventListener(
        "popstate",
        handlePopState,
        true
      );

      window.removeEventListener(
        "pageshow",
        checkSession
      );

      window.removeEventListener(
        "storage",
        checkSession
      );

      window.removeEventListener(
        "golden-dreams-logout",
        checkSession
      );

      document.removeEventListener(
        "visibilitychange",
        checkSession
      );
    };
  }, []);

  if (!isAuthenticated) {
    return <Navigate to="/login" replace />;
  }

  return children;
}

/* =========================================================
   MIDNIGHT GOLD BACKGROUND ANIMATION
========================================================= */

function MidnightGoldAnimation() {
  const particles = useMemo(
    () =>
      Array.from({ length: 42 }, (_, i) => ({
        id: i,
        left: Math.random() * 100,
        top: Math.random() * 100,
        size: 1.5 + Math.random() * 3.5,
        duration: 7 + Math.random() * 10,
        delay: Math.random() * 8,
        drift: 28 + Math.random() * 55,
        brightness: 0.35 + Math.random() * 0.65,
      })),
    []
  );

  const lightTrails = useMemo(
    () =>
      Array.from({ length: 3 }, (_, i) => ({
        id: i,
        top: 18 + i * 31 + Math.random() * 12,
        duration: 14 + Math.random() * 8,
        delay: i * 5,
        width: 100 + Math.random() * 100,
      })),
    []
  );

  return (
    <Box
      aria-hidden="true"
      sx={{
        position: "absolute",
        inset: 0,
        overflow: "hidden",
        pointerEvents: "none",
        zIndex: 0,
        background: `
          radial-gradient(
            ellipse at 50% 0%,
            rgba(116, 82, 12, 0.13) 0%,
            transparent 48%
          ),
          radial-gradient(
            ellipse at 90% 80%,
            rgba(184, 134, 11, 0.07) 0%,
            transparent 45%
          )
        `,
      }}
    >
      {/* Subtle ambient gold glow */}

      <motion.div
        animate={{
          opacity: [0.25, 0.55, 0.25],
          scale: [1, 1.12, 1],
        }}
        transition={{
          duration: 12,
          repeat: Infinity,
          ease: "easeInOut",
        }}
        style={{
          position: "absolute",
          width: "min(70vw, 650px)",
          height: "min(70vw, 650px)",
          left: "50%",
          top: "38%",
          transform: "translate(-50%, -50%)",
          borderRadius: "50%",
          background:
            "radial-gradient(circle, rgba(218,165,32,0.09) 0%, rgba(184,134,11,0.035) 38%, transparent 70%)",
          filter: "blur(25px)",
        }}
      />

      {/* Floating golden dust */}

      {particles.map((particle) => (
        <motion.div
          key={particle.id}
          initial={{
            opacity: 0,
            scale: 0.4,
          }}
          animate={{
            y: [
              0,
              -particle.drift,
              -particle.drift * 0.4,
              0,
            ],
            x: [
              0,
              particle.drift * 0.25,
              -particle.drift * 0.2,
              0,
            ],
            opacity: [
              0.08,
              particle.brightness,
              0.2,
              particle.brightness * 0.8,
              0.08,
            ],
            scale: [0.6, 1.25, 0.85, 1.15, 0.6],
          }}
          transition={{
            duration: particle.duration,
            delay: particle.delay,
            repeat: Infinity,
            ease: "easeInOut",
          }}
          style={{
            position: "absolute",
            top: `${particle.top}%`,
            left: `${particle.left}%`,
            width: `${particle.size}px`,
            height: `${particle.size}px`,
            borderRadius: "50%",
            background:
              "radial-gradient(circle, #fff9dc 0%, #ffd76a 38%, #b8860b 100%)",
            boxShadow: `
              0 0 5px rgba(255, 215, 0, 0.7),
              0 0 12px rgba(218, 165, 32, 0.32)
            `,
            willChange: "transform, opacity",
          }}
        />
      ))}

      {/* Slow-moving celestial light trails */}

      {lightTrails.map((trail) => (
        <motion.div
          key={`trail-${trail.id}`}
          initial={{
            x: "-30vw",
            opacity: 0,
          }}
          animate={{
            x: ["-30vw", "130vw"],
            opacity: [0, 0.5, 0.35, 0],
          }}
          transition={{
            duration: trail.duration,
            delay: trail.delay,
            repeat: Infinity,
            repeatDelay: 5,
            ease: "linear",
          }}
          style={{
            position: "absolute",
            top: `${trail.top}%`,
            left: 0,
            width: `${trail.width}px`,
            height: "1px",
            background:
              "linear-gradient(90deg, transparent, rgba(255,215,100,0.8), rgba(255,248,220,0.9), transparent)",
            boxShadow: "0 0 8px rgba(255, 215, 0, 0.35)",
            transform: "rotate(-18deg)",
            transformOrigin: "left center",
            willChange: "transform, opacity",
          }}
        />
      ))}

      {/* Occasional larger golden sparkles */}

      {[0, 1, 2, 3, 4, 5].map((i) => (
        <motion.div
          key={`sparkle-${i}`}
          animate={{
            opacity: [0, 0.9, 0],
            scale: [0.5, 1.5, 0.5],
            rotate: [0, 45, 90],
          }}
          transition={{
            duration: 3 + (i % 3),
            delay: i * 1.7,
            repeat: Infinity,
            repeatDelay: 4 + i,
            ease: "easeInOut",
          }}
          style={{
            position: "absolute",
            top: `${12 + ((i * 17) % 76)}%`,
            left: `${8 + ((i * 19) % 84)}%`,
            width: "5px",
            height: "5px",
            background: "#ffe6a0",
            borderRadius: "50%",
            boxShadow:
              "0 0 8px 2px rgba(255, 215, 0, 0.65)",
            willChange: "transform, opacity",
          }}
        />
      ))}
    </Box>
  );
}

/* =========================================================
   MAIN APP
========================================================= */

function App() {
  const isMobile = useMediaQuery("(max-width: 768px)");
  const location = useLocation();
  const [showSplash, setShowSplash] = useState(true);
    useEffect(() => {
      const timer = setTimeout(() => {
        setShowSplash(false);
      }, 2500);

  return () => clearTimeout(timer);
}, []);
  const navbarPages = [
    "/",
    "/pricing",
    "/features",
    "/contact",
    "/store",
    "/live",
    "/login",
  ];

  const showNavbar = navbarPages.includes(location.pathname);

  return (
    <div className="App">
      {showSplash && <SplashScreen />}
      <Box
        sx={{
          position: "relative",
          isolation: "isolate",
          minHeight: "100vh",
          width: "100%",
          overflow: "hidden",
          boxSizing: "border-box",
          color: "#ffffff",
          background:
            "linear-gradient(135deg, #030303 0%, #0a0906 48%, #11100c 100%)",
        }}
      >
        {/* BACKGROUND MOTION */}

        <MidnightGoldAnimation />

        {/* ALL PAGE CONTENT STAYS ABOVE THE ANIMATION */}

        <Box
          sx={{
            position: "relative",
            zIndex: 1,
            width: "100%",
            minHeight: "100vh",
            display: "flex",
            flexDirection: "column",
          }}
        >
          {/* PUBLIC NAVBAR */}

          {showNavbar &&
            (isMobile ? <MobileNavbar /> : <Navbar />)}

          {/* ROUTES */}

          <Box
            component="main"
            sx={{
              width: "100%",
              flex: "1 0 auto",
              position: "relative",
            }}
          >
            <ScrollToTop />

            <Routes>
              {/* Public pages */}

              <Route path="/" element={<Home />} />

              <Route
                path="/pricing"
                element={<Pricing />}
              />

              <Route
                path="/features"
                element={<Features />}
              />

              <Route
                path="/store"
                element={<Store />}
              />

              <Route
                path="/contact"
                element={<ContactUs />}
              />

              <Route
                path="/live"
                element={<Live />}
              />

              <Route
                path="/learn-more"
                element={<LearnMore />}
              />

              <Route
                path="/login"
                element={<Login />}
              />

              {/* Protected dashboard */}

              <Route
                path="/dashboard"
                element={
                  <ProtectedRoute>
                    <>
                      <DashboardNavbar />
                      <LoginComponent />
                      <LoginFooter />
                    </>
                  </ProtectedRoute>
                }
              />

              {/* Unknown URLs return to the home page */}

              <Route
                path="*"
                element={<Navigate to="/" replace />}
              />
            </Routes>
          </Box>

          {/* PUBLIC FOOTER: HIDDEN ON DASHBOARD */}

          {location.pathname !== "/dashboard" && (
            <Footer />
          )}
        </Box>
      </Box>
    </div>
  );
}

export default App;
